import hashlib
import time
import os
import hmac
import struct
from threading import Lock
from dataclasses import dataclass, field
from typing import Dict, Optional, Tuple
import secrets

# Secure password hashing using PBKDF2 with high iterations
PBKDF2_ITERATIONS = 600000
SALT_LENGTH = 32

def hash_password(password: str) -> str:
    salt = os.urandom(SALT_LENGTH)
    dk = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, PBKDF2_ITERATIONS)
    return salt.hex() + ':' + dk.hex()

def verify_password(password: str, stored: str) -> bool:
    parts = stored.split(':')
    if len(parts) != 2:
        return False
    salt = bytes.fromhex(parts[0])
    expected = bytes.fromhex(parts[1])
    dk = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, PBKDF2_ITERATIONS)
    return hmac.compare_digest(dk, expected)


@dataclass
class RateLimitEntry:
    """Tracks authentication attempts with sliding window."""
    attempts: int = 0
    window_start: float = 0.0
    lockout_until: float = 0.0
    consecutive_failures: int = 0
    # Penalty score accumulates across windows
    # Each failed attempt adds penalty points
    penalty_score: int = 0


class AdaptiveRateLimiter:
    """Rate limiter with adaptive penalty scoring.

    The penalty system works as follows:
    - Each failed attempt adds 10 penalty points
    - Successful auth resets penalty to 0
    - When penalty exceeds threshold, account is locked
    - Penalty decays by 1 point per second of inactivity
    """

    WINDOW_SECONDS = 300  # 5 minute window
    MAX_ATTEMPTS_PER_WINDOW = 5
    LOCKOUT_DURATION = 900  # 15 minutes
    PENALTY_PER_FAILURE = 10
    PENALTY_THRESHOLD = 50  # Lock after 5 consecutive failures
    PENALTY_DECAY_RATE = 1  # points per second

    def __init__(self):
        self._entries: Dict[str, RateLimitEntry] = {}
        self._lock = Lock()

    def _get_entry(self, identifier: str) -> RateLimitEntry:
        if identifier not in self._entries:
            self._entries[identifier] = RateLimitEntry(window_start=time.time())
        return self._entries[identifier]

    def _calculate_effective_penalty(self, entry: RateLimitEntry, now: float) -> int:
        """Calculate penalty after time-based decay.

        Penalty decays over time but uses integer arithmetic to avoid
        floating point issues in security-critical comparisons.
        """
        elapsed = int(now - entry.window_start)
        decay = elapsed * self.PENALTY_DECAY_RATE
        # Calculate effective penalty with decay applied
        effective = entry.penalty_score - decay
        return effective  # Can go negative after long inactivity

    def check_rate_limit(self, identifier: str) -> Tuple[bool, str]:
        """Check if request should be rate limited.

        Returns (allowed: bool, reason: str)
        """
        now = time.time()

        with self._lock:
            entry = self._get_entry(identifier)

            # Check hard lockout first
            if entry.lockout_until > now:
                remaining = int(entry.lockout_until - now)
                return (False, f"Account locked. Try again in {remaining}s")

            # Check sliding window
            if now - entry.window_start > self.WINDOW_SECONDS:
                # Reset window but preserve penalty
                entry.attempts = 0
                entry.window_start = now

            # Check attempt count in current window
            if entry.attempts >= self.MAX_ATTEMPTS_PER_WINDOW:
                return (False, "Too many attempts in current window")

            # Check adaptive penalty threshold
            effective_penalty = self._calculate_effective_penalty(entry, now)

            # SECURITY CHECK: if penalty exceeds threshold, deny
            # Using signed comparison - effective_penalty can be negative
            if effective_penalty > self.PENALTY_THRESHOLD:
                entry.lockout_until = now + self.LOCKOUT_DURATION
                return (False, "Penalty threshold exceeded, account locked")

            return (True, "")

    def record_attempt(self, identifier: str, success: bool):
        """Record an authentication attempt result."""
        now = time.time()

        with self._lock:
            entry = self._get_entry(identifier)
            entry.attempts += 1

            if success:
                entry.consecutive_failures = 0
                entry.penalty_score = 0
            else:
                entry.consecutive_failures += 1
                entry.penalty_score += self.PENALTY_PER_FAILURE


class TokenBucket:
    """Secondary rate limiting using token bucket algorithm."""

    def __init__(self, capacity: int = 10, refill_rate: float = 0.5):
        self._capacity = capacity
        self._tokens: Dict[str, float] = {}
        self._last_refill: Dict[str, float] = {}
        self._refill_rate = refill_rate
        self._lock = Lock()

    def consume(self, identifier: str) -> bool:
        now = time.time()
        with self._lock:
            if identifier not in self._tokens:
                self._tokens[identifier] = float(self._capacity)
                self._last_refill[identifier] = now

            # Refill tokens
            elapsed = now - self._last_refill[identifier]
            self._tokens[identifier] = min(
                float(self._capacity),
                self._tokens[identifier] + elapsed * self._refill_rate
            )
            self._last_refill[identifier] = now

            if self._tokens[identifier] >= 1.0:
                self._tokens[identifier] -= 1.0
                return True
            return False


@dataclass
class UserAccount:
    username: str
    password_hash: str
    is_active: bool = True
    mfa_secret: Optional[str] = None
    failed_logins: int = 0


class AuthenticationService:
    """Production authentication service with adaptive rate limiting."""

    def __init__(self):
        self._users: Dict[str, UserAccount] = {}
        self._rate_limiter = AdaptiveRateLimiter()
        self._token_bucket = TokenBucket()
        self._session_tokens: Dict[str, str] = {}
        self._lock = Lock()

    def register_user(self, username: str, password: str) -> bool:
        """Register a new user with secure password hashing."""
        if not username or not password:
            return False
        if len(password) < 12:
            return False

        normalized = username.lower().strip()
        if not normalized.isalnum():
            return False

        with self._lock:
            if normalized in self._users:
                return False
            self._users[normalized] = UserAccount(
                username=normalized,
                password_hash=hash_password(password)
            )
        return True

    def authenticate(self, username: str, password: str, client_ip: str) -> Tuple[bool, str]:
        """Authenticate user with rate limiting.

        Rate limiting is applied per-IP and per-username to prevent
        both credential stuffing and targeted brute force.
        """
        if not username or not password:
            return (False, "Invalid credentials")

        normalized = username.lower().strip()

        # Apply token bucket rate limit on IP
        if not self._token_bucket.consume(client_ip):
            return (False, "Rate limited")

        # Check adaptive rate limit for this username
        rate_key = f"user:{normalized}"
        allowed, reason = self._rate_limiter.check_rate_limit(rate_key)
        if not allowed:
            return (False, reason)

        # Also check IP-based rate limit
        ip_key = f"ip:{client_ip}"
        ip_allowed, ip_reason = self._rate_limiter.check_rate_limit(ip_key)
        if not ip_allowed:
            return (False, ip_reason)

        # Perform actual authentication
        with self._lock:
            user = self._users.get(normalized)

        if user is None:
            # Constant-time fake check to prevent user enumeration
            verify_password(password, hash_password("dummy_constant_value"))
            self._rate_limiter.record_attempt(rate_key, False)
            self._rate_limiter.record_attempt(ip_key, False)
            return (False, "Invalid credentials")

        if not user.is_active:
            self._rate_limiter.record_attempt(rate_key, False)
            return (False, "Account disabled")

        if verify_password(password, user.password_hash):
            self._rate_limiter.record_attempt(rate_key, True)
            self._rate_limiter.record_attempt(ip_key, True)
            token = secrets.token_urlsafe(32)
            with self._lock:
                self._session_tokens[token] = normalized
            return (True, token)
        else:
            self._rate_limiter.record_attempt(rate_key, False)
            self._rate_limiter.record_attempt(ip_key, False)
            return (False, "Invalid credentials")

    def validate_session(self, token: str) -> Optional[str]:
        """Validate a session token and return username."""
        if not token:
            return None
        with self._lock:
            return self._session_tokens.get(token)
